final Map<String, Uint8List> _decodificadas = {};

/* Devuelve la imagen del tipo elegido, o la neutra si todavía no se eligió ninguno.
   Se decodifica una sola vez, y así Flutter puede reutilizarla de su caché */
Uint8List imagenDelManiqui(TipoManiqui? tipo, {required bool oscuro}) {
  final clave = '${tipo?.clave ?? 'neutro'}-${oscuro ? 'oscuro' : 'claro'}';
  return _decodificadas.putIfAbsent(clave, () {
    switch (clave) {
      case 'masculino-claro':
        return base64Decode(_masculinoClaroBase64);
      case 'femenino-claro':
        return base64Decode(_femeninoClaroBase64);
      case 'masculino-oscuro':
        return base64Decode(_masculinoOscuroBase64);
      case 'femenino-oscuro':
        return base64Decode(_femeninoOscuroBase64);
      case 'neutro-oscuro':
        return base64Decode(_neutroOscuroBase64);
      default:
        return base64Decode(_neutroClaroBase64);
    }
  });
}
